using System.Net;
using Vitarish.Communications.Contracts.Errors;
using Vitarish.Communications.Contracts.Reminders;
using Vitarish.Communications.Contracts.Requests;
using Vitarish.Communications.Contracts.Responses;
using Vitarish.Communications.Contracts.Results;
using Vitarish.Communications.Contracts.Routes;
using Vitarish.Modules.Base.Client;
namespace Vitarish.Communications.Client;
public sealed class CommunicationsClient(HttpClient httpClient) : AuthenticatedModuleApiClient(httpClient), ICommunicationsClient
{
    public async Task<CommunicationsCommandResult> SendEmailAsync(SendEmailRequest request, CancellationToken cancellationToken = default) => MapCommand(await PostJsonAsync<SendEmailRequest, CommunicationsCommandResult>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.SendEmail, request, cancellationToken));
    public async Task<CommunicationsCommandResult> SendSmsAsync(SendSmsRequest request, CancellationToken cancellationToken = default) => MapCommand(await PostJsonAsync<SendSmsRequest, CommunicationsCommandResult>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.SendSms, request, cancellationToken));
    public async Task<CommunicationsCommandResult> SendSmsCodeAsync(SendSmsCodeRequest request, CancellationToken cancellationToken = default) => MapCommand(await PostJsonAsync<SendSmsCodeRequest, CommunicationsCommandResult>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.SendSmsCode, request, cancellationToken));
    public async Task<CommunicationsCommandResult> SendSmsReminderAsync(SendSmsReminderRequest request, CancellationToken cancellationToken = default) => MapCommand(await PostJsonAsync<SendSmsReminderRequest, CommunicationsCommandResult>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.SendSmsReminder, request, cancellationToken));
    public async Task<CommunicationsQueryResult<SmsDeliveryStateResponse>> GetSmsDeliveryStateAsync(long messageId, CancellationToken cancellationToken = default) => MapQuery(await GetJsonAsync<SmsDeliveryStateResponse>(CommunicationsApiRoutes.Base+$"/messages/sms/{messageId}/delivery-state", cancellationToken));
    public async Task<CommunicationsQueryResult<IReadOnlyList<ReminderReadDto>>> GetRemindersAsync(ReminderDescriptorDto descriptor, CancellationToken cancellationToken = default) => MapQuery(await PostJsonAsync<ReminderDescriptorDto, IReadOnlyList<ReminderReadDto>>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.Reminders+"/query", descriptor, cancellationToken));
    public async Task<CommunicationsQueryResult<IReadOnlyList<ReminderReadDto>>> GetRemindersBySourceAsync(Guid sourceId, CancellationToken cancellationToken = default) => MapQuery(await GetJsonAsync<IReadOnlyList<ReminderReadDto>>(CommunicationsApiRoutes.Base+$"/reminders/source/{sourceId}", cancellationToken));
    public async Task<CommunicationsQueryResult<ReminderReadDto>> CreateReminderAsync(ReminderWriteDto request, CancellationToken cancellationToken = default) => MapQuery(await PostJsonAsync<ReminderWriteDto, ReminderReadDto>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.Reminders, request, cancellationToken));
    public async Task<CommunicationsQueryResult<IReadOnlyList<ReminderReadDto>>> CreateRemindersAsync(ReminderRangeCreateRequest request, CancellationToken cancellationToken = default) => MapQuery(await PostJsonAsync<ReminderRangeCreateRequest, IReadOnlyList<ReminderReadDto>>(CommunicationsApiRoutes.Base+CommunicationsApiRoutes.ReminderRange, request, cancellationToken));
    public async Task<CommunicationsQueryResult<ReminderReadDto>> UpdateReminderAsync(ReminderUpdateRequest request, CancellationToken cancellationToken = default) => MapQuery(await PutJsonAsync<ReminderUpdateRequest, ReminderReadDto>(CommunicationsApiRoutes.Base+$"/reminders/{request.Id}", request, cancellationToken));
    public async Task<CommunicationsCommandResult> DeleteReminderAsync(Guid id, CancellationToken cancellationToken = default) => MapCommand(await DeleteJsonAsync<CommunicationsCommandResult>(CommunicationsApiRoutes.Base+$"/reminders/{id}", cancellationToken));
    public async Task<CommunicationsCommandResult> MarkReminderSentAsync(Guid id, MarkReminderSentRequest request, CancellationToken cancellationToken = default) => MapCommand(await PostJsonAsync<MarkReminderSentRequest, CommunicationsCommandResult>(CommunicationsApiRoutes.Base+$"/reminders/{id}/sent", request, cancellationToken));
    protected override ModuleApiClientFailure CreateFailure(HttpStatusCode statusCode, string message, int? statusCodeValue) => new(statusCode.ToString(), message, statusCodeValue);
    private static CommunicationsCommandResult MapCommand(ModuleApiClientResult<CommunicationsCommandResult> r)=> r.IsSuccess ? r.Value! : CommunicationsCommandResult.Failed(ToCommandStatus(r.Failure!), ToError(r.Failure!));
    private static CommunicationsQueryResult<T> MapQuery<T>(ModuleApiClientResult<T> r)=> r.IsSuccess ? CommunicationsQueryResult<T>.Success(r.Value!) : CommunicationsQueryResult<T>.Failed(ToError(r.Failure!));
    private static CommunicationsError ToError(ModuleApiClientFailure f)=>new(ToErrorCode(f), f.Message);
    private static CommunicationsCommandStatus ToCommandStatus(ModuleApiClientFailure f)=> ToErrorCode(f) switch { CommunicationsErrorCode.ValidationFailure=>CommunicationsCommandStatus.ValidationFailure, CommunicationsErrorCode.Unauthorized=>CommunicationsCommandStatus.Unauthorized, CommunicationsErrorCode.Forbidden=>CommunicationsCommandStatus.Forbidden, CommunicationsErrorCode.Duplicate=>CommunicationsCommandStatus.Duplicate, CommunicationsErrorCode.ProviderUnavailable=>CommunicationsCommandStatus.ProviderUnavailable, CommunicationsErrorCode.ProviderRejected=>CommunicationsCommandStatus.ProviderRejected, CommunicationsErrorCode.Timeout=>CommunicationsCommandStatus.Timeout, CommunicationsErrorCode.Cancellation=>CommunicationsCommandStatus.Cancellation, _=>CommunicationsCommandStatus.UnexpectedFailure };
    private static CommunicationsErrorCode ToErrorCode(ModuleApiClientFailure f)=> f.Code switch { "Canceled"=>CommunicationsErrorCode.Cancellation, "Timeout"=>CommunicationsErrorCode.Timeout, "Transport"=>CommunicationsErrorCode.TransportFailure, "Deserialization"=>CommunicationsErrorCode.DeserializationFailure, nameof(HttpStatusCode.BadRequest)=>CommunicationsErrorCode.ValidationFailure, nameof(HttpStatusCode.Unauthorized)=>CommunicationsErrorCode.Unauthorized, nameof(HttpStatusCode.Forbidden)=>CommunicationsErrorCode.Forbidden, nameof(HttpStatusCode.NotFound)=>CommunicationsErrorCode.NotFound, nameof(HttpStatusCode.Conflict)=>CommunicationsErrorCode.Duplicate, nameof(HttpStatusCode.ServiceUnavailable)=>CommunicationsErrorCode.ProviderUnavailable, nameof(HttpStatusCode.GatewayTimeout)=>CommunicationsErrorCode.Timeout, _=>CommunicationsErrorCode.UnexpectedFailure };
}
